('oct-2026-323138',NULL,'2026-10','323138','BB - DEPOSITO SÃO PAULO','ED. DEPÓSITO SOROCABA (SP)','Recepção','ITENS DA ORDEM DE SERVIÇO','01/10/2026 00:11:39','20/10/2026 00:00:00','Aberta','Periodicidad
Descrição
e
Veriﬁcar e corrigir se necessário: Se a pintura do barrilete está descascando e se as válvulas estão em
suas devidas posições ?aberta? ou ?fechada?
MENSAL
Conformidade: -
Veriﬁcar o funcionamento dos alarmes de incêndios e gongos hidráulicos
MENSAL
Conformidade: -
Se a estrutura dos tanques elevados necessitam de reparos.
MENSAL
Conformidade: -
Inspecionar e substituir se necessário os detectores quando:
Se repõe em funcionamento um sistema que ﬁcou desativado por tempo superior a 6 meses, Há
MENSAL detectores que apresentem sinais de avarias mecânicas ou corrosão interna, Os detectores tenham
Conformidade: -
No caso de haver intertravamento do sistema de ar condicionado, ventiladores, "dumpers", etc, veriﬁcar
se estes estão funcionando controlados pelos detectores
MENSAL
Conformidade: -
Testar a falta de corrente contínua e de corrente alternada no sistema
MENSAL
Conformidade: -
Se as válvulas, registros e vigias estão limpos, desobstruídos e sem ferrugem
MENSAL
Conformidade: -
Veriﬁcar e corrigir se necessário: Se as vigias estão devidamente fechadas.
MENSAL
Conformidade: -
Veriﬁcar se a conexão hidráulica para o Corpo de Bombeiros está com tampão e os ﬁos da rosca ou
engate em boas condições e dentro do padrão exigido no local
MENSAL
Conformidade: -
Veriﬁcações da bomba
1) O funcionamento das bombas d´água do sistema (partida e parada), 2) O controle e a comutação das
bombas d´água do sistema3) Se as pressões de entrada e saída das bombas de água estão de acordo
MENSAL
com o projeto
Conformidade: -
Veriﬁcações da válvula
1) Se as válvulas apresentam danos mecânicos, ferrugem, pintura descascada, etc 2) Se as válvulas de
teste e dreno estão lacradas, na posição fechada, e se a válvula de controle está lacrada na posição
MENSAL
aberta 3) Se as válvulas estão com seus
Conformidade: -
Veriﬁcar se os acionadores manuais estão com o vidro em boas condições e o martelo no local
apropriado
MENSAL
Conformidade: -
Veriﬁcar as pressões na tubulação com a bomba de água a plena carga.
MENSAL
Conformidade: -
Veriﬁcar os pressostatos instalados nas válvulas de controle e alarme do sistema
MENSAL
Conformidade: -
Veriﬁcar se o som dos alarmes é audível em todos os pontos da ediﬁcação com os equipamentos dos
ambientes funcionando normalmente.
MENSAL
Conformidade: -
Veriﬁcar e corrigir se necessário: Se há vazamentos e inﬁltrações de água através das paredes do
reservatório
MENSAL
Conformidade: -
Inspecionar visualmente o estado geral da bateria
MENSAL
Conformidade: -
Veriﬁcações de tubulações
1) Os ﬁltros das tubulações 2) A existência de ferrugem nas tubulações, através de drenagem de água
MENSAL
Conformidade: -
Veriﬁcar e corrigir se necessário: Se a reserva técnica de incêndio está sendo mantida, registrando o
nível observado
MENSAL
Conformidade: -
Veriﬁcar se os leds dos detectores indicam corretamente o seu funcionamento
MENSAL
Conformidade: -
Veriﬁcar e corrigir se necessário: Se há vigias que possibilitem o funcionamento de bombas de incêndio
do Corpo de Bombeiros, para recalque de água, na impossibilidade do uso de bombas locais
MENSAL
Conformidade: -
Se há vazamentos e inﬁltrações de água através das paredes do reservatório
MENSAL
Conformidade: -
Veriﬁcar se há luminárias ou estocagem de mercadorias muito próximas (menos de 1 metro) dos
chuveiros
MENSAL
Conformidade: -
Veriﬁcar: 1)Se os chuveiros estão limpos e sem pintura, e não estão amassados 2)Se não há mistura de
bicos de cores diferentes, mantendo em todo o ambiente as cores deﬁnidas no projeto
MENSAL
Conformidade: -
Veriﬁcar o funcionamento das chaves de ﬂuxo instaladas nos ramais de alimentação de cada pavimento,
se houver
MENSAL
Conformidade: -
Veriﬁcar o estado de conservação e funcionamento dos tanques de pressão, se houver
MENSAL
Conformidade: -
Simular defeitos e fogo através dos dispositivos disponíveis na central com a ﬁnalidade de veriﬁcar a
atuação dos indicadores sonoros e visuais
MENSAL
Conformidade: -
Veriﬁcar e corrigir se necessário: Se a estrutura dos tanques elevados necessitam de reparos
MENSAL
Conformidade: -
Veriﬁcar se o acionamento do alarme dos pavimentos ou setores para o painel central está em ordem e
deste para todo o prédio
MENSAL
Conformidade: -
Veriﬁcar o estado geral das chaves e comandos da central, quanto ao aspecto e condições de operação,
lâmpadas ou fusíveis queimados, etc
MENSAL
Conformidade: -
Veriﬁcar e corrigir se necessário: Se as válvulas, registros e vigias estão limpos, desobstruídos e sem
ferrugem
MENSAL
Conformidade: -
Se há vigias que possibilitem o funcionamento de bombas de incêndio do Corpo de Bombeiros, para
recalque de água, na impossibilidade do uso de bombas locais
MENSAL
Conformidade: -
Veriﬁcar a existência de suportes ou suspensões quebradas, bicos plugados ou mal posicionados,
tubulações amassadas, etc
MENSAL
Conformidade: -
Ensaiar os detectores de chamas de acordo com as instruções dos fabricantes
SEMESTRAL
Conformidade: -
Testar a isolação entre os condutores e a terra nos','16482Central de alarme - Recepção 91 NORMAL - NORMAL','hidraulica','EVERSON VICENTE FERREIRA - BOMBEIRO HIDRÁULICO','Atribuída','Ordem de serviço / Chamado técnico Nº.: 323138 /

